import { ApiError, NetworkError, ResponseShapeError, type ClientError } from "./errors.ts";
import {
  parseCoachesResponse,
  parseErrorBody,
  parseSessionDetails,
  parseSessionsResponse,
} from "./mappers.ts";
import type {
  CoachesResponse,
  CreateSessionRequest,
  SessionDetails,
